function norm(s){return String(s).toLowerCase().replace(/[’']/g,'').replace(/≥/g,'>=').replace(/≤/g,'<=').replace(/≠/g,'!=').replace(/[−–—]/g,'-').replace(/=>/g,'>=').replace(/=</g,'<=').replace(/^(a|an|the)\s+/,'').replace(/[^a-z0-9+·′ø.\-<>=!\/*^]/g,'').replace(/\.$/,'')}
