 function add(n,tg,topics,follow){for(var i=0;i<n;i++){var id=coachPick({topics:topics||ALL,exclude:used,last:last,target:tg});if(!id)break;used.push(id);last.push(QS[QI[id]].t);steps.push({k:'try',it:mkItem(id)})}}
