 var dots=el.querySelector('#dots'),N=14,pos=[];for(var i=0;i<N;i++){pos.push(i/N);dots.insertAdjacentHTML('beforeend','<circle r="3" fill="var(--pri)" stroke="none"></circle>')}
 var cs=dots.children,I=0.5,last=0;function path(t){t=t%1;var L=[200,80,200,80],x,y,d=t*560;if(d<200){x=30+d;y=25}else if(d<280){x=230;y=25+(d-200)}else if(d<480){x=230-(d-280);y=105}else{x=30;y=105-(d-480)}return[x,y]}
 function frame(ts){if(!el.isConnected)return;var dt=Math.min(.05,(ts-last)/1000||0);last=ts;for(var i=0;i<N;i++){pos[i]=(pos[i]+dt*Math.min(1.2,I*.5))%1;var p=path(pos[i]);cs[i].setAttribute('cx',p[0]);cs[i].setAttribute('cy',p[1])}requestAnimationFrame(frame)}
