 var G={AND:function(a,b){return a&b},OR:function(a,b){return a|b},NAND:function(a,b){return 1-(a&b)},NOR:function(a,b){return 1-(a|b)},XOR:function(a,b){return a^b},XNOR:function(a,b){return 1-(a^b)}},g='AND',a=0,b=0,gs=el.querySelector('#gs');
