  h+='<div class="small mute">Parts: '+p.map(function(v,i){return 'R'+(i+1)+' = '+eng(v)}).join(' · ')+'. Tap R1, R2, R3 below to swap parts.</div><div class="mbtns">'+[[0,1],[1,2],[0,2]].map(function(q){return '<button class="btn sec sm" data-a="swap" data-v="'+q.join(',')+'">swap R'+(q[0]+1)+' ↔ R'+(q[1]+1)+'</button>'}).join('')+'</div>';
