 check:function(s){var ok=s.dx===s.f,nm=FAULTS.filter(function(x){return x[0]===s.f})[0][1],eff=s.n<=3,sc=(ok?.8:0)+(ok&&eff?.2:0);return {score:sc,lines:[[ok,ok?'Correct: '+nm+'.':'The fault was: '+nm+'.'],[ok&&eff,'You used '+s.n+' measurement'+(s.n===1?'':'s')+(eff?'. Efficient.':'. Aim for three or fewer.')]],steps:['Turn power off and look first: loose, reversed or missing parts.','In a <b>series</b> loop the same current flows everywhere, so a break stops all of it.','The part that shows the <b>full source voltage</b> ('+s.Vs+' V) across it is the open part: all the voltage drops across the break.','A part that reads <b>0 V</b> while others read the full voltage is shorted (its twin gets the whole supply and glows brighter).','If the battery itself reads near 0 V, it is dead or overloaded. Replace it before looking further.','Here: '+nm+'.']}},
