function ledMeter(s){var I=ledI(s),burn=I>25;return meterBox(sig(I,3)+' mA',burn?'<b style="color:#ff9aa5">LED burned out!</b> Too much current':I<s.If*.7?'Dim: not enough current':'Current through the LED')}
