/* 5. Logic from a truth table */
var LOPS=['AND','OR','XOR','NAND','NOR'],LIN=['A','A′','B','B′','C','C′'];
function lop(o,a,b){return o==='AND'?a&b:o==='OR'?a|b:o==='XOR'?a^b:o==='NAND'?1-(a&b):1-(a|b)}
function lin(x,A,B,C){var v=x[0]==='A'?A:x[0]==='B'?B:C;return x.length>1?1-v:v}
function lgY(g,A,B,C){return lop(g.o2,lop(g.o1,lin(g.x1,A,B,C),lin(g.x2,A,B,C)),lin(g.x3,A,B,C))}
