 range:function(s,k,v){s[k]=v;$('mn').textContent=s.N;$('mb').textContent=s.B;$('mgv').innerHTML=magView(s)},
 act:function(s,a,v){if(a==='core'){s.core=+v;return true}if(a==='rec'){s.rec.push({N:s.N,B:s.B,core:s.core,c:magClips(s)});return true}return false},
 check:function(s){var c=magClips(s),inL=s.N<=s.maxN&&s.B<=s.maxB,ok=c>=s.T&&inL,tr=s.rec.length>=2;return {score:(c>=s.T?.5:0)+(inL?.25:0)+(tr?.25:0),lines:[[c>=s.T,'Your setup lifts '+c+' clip'+(c===1?'':'s')+' (needed '+s.T+').'],[inL,inL?'You stayed within the limits.':'You exceeded the turn or battery limit.'],[tr,tr?'You compared at least two trials.':'Change one variable at a time and record at least two trials.']],steps:['Strength depends on <b>current</b>, <b>number of turns</b> and the <b>core</b>: more turns, more current, and a soft iron core make it stronger.','Test <b>one variable at a time</b> (same battery, double the turns; then same turns, add a battery). Otherwise you cannot tell what helped.','A soft iron core concentrates the magnetic field far more than an air core, so it is the biggest single improvement.','Do not exceed the battery limit: a short, thick coil on a big supply gets hot and drains the battery.','Always disconnect the battery between trials.']}},
