var EF=[[65,85,'EF0'],[86,110,'EF1'],[111,135,'EF2'],[136,165,'EF3'],[166,200,'EF4'],[201,260,'EF5']],FF=[[40,72,'F0'],[73,112,'F1'],[113,157,'F2'],[158,206,'F3'],[207,260,'F4'],[261,318,'F5']];
