 view:function(s){return s.hur?msel(s,'cat','Rating',['Tropical depression','Tropical storm','Category 1','Category 2','Category 3','Category 4','Category 5'])+msel(s,'maj','Is it a major hurricane?',['Yes','No']):msel(s,'sc','Which scale applies?',[['F','Fujita (F) scale'],['EF','Enhanced Fujita (EF) scale']])+msel(s,'r','Rating',['0','1','2','3','4','5'].map(function(x){return [x,'Rating '+x]}))},
 act:function(s,a,v){s.in[a]=v;return false},
